	xr5 ^= ((c5.s0[byte(xl5>>24)] + c5.s1[byte(xl5>>16)]) ^ c5.s2[byte(xl5>>8)]) + c5.s3[byte(xl5)] ^ c5.p[1]
	xr6 ^= ((c6.s0[byte(xl6>>24)] + c6.s1[byte(xl6>>16)]) ^ c6.s2[byte(xl6>>8)]) + c6.s3[byte(xl6)] ^ c6.p[1]
