// run8 hashes exactly 8 candidates through interleaved lanes,
// writing verdicts to h.verdicts[:8].
func (h *Hasher) run8(pw [][]byte) {
	var keys [8][]byte
	var c [8]*state
	for i := 0; i < 8; i++ {
		// bug compatibility: the key's trailing NUL participates
		k := append(h.keyScratch[i][:0], pw[i]...)
		k = append(k, 0)
		h.keyScratch[i] = k
		keys[i] = k
		// no zeroing: initState overwrites p and s0..s3 in full;
		// clearing 4 KB per lane per batch would be pure waste.
		c[i] = &h.scratch[i]
		initState(c[i])
	}
	salt := h.csalt[:]
	expandKeyWithSalt8(keys, salt, c)
	var saltKeys [8][]byte
	for i := 0; i < 8; i++ {
		saltKeys[i] = salt
	}
	for r, rounds := uint64(0), uint64(1)<<uint(h.cost); r < rounds; r++ {
		expandKey8(keys, c)
		expandKey8(saltKeys, c)
	}
	for i := 0; i < 8; i++ {
		h.verdicts[i] = h.finish(c[i])
	}
}
